/**
 * Microsoft Teams Node - Version 2
 * Discriminator: resource=activityNotification, operation=send
 */


interface Credentials {
  microsoftTeamsOAuth2Api: CredentialReference;
  microsoftOAuth2Api: CredentialReference;
  microsoftEntraServicePrincipalApi: CredentialReference;
}

/** Send a notification to the activity feed of a user */
export type MicrosoftTeamsV2ActivityNotificationSendParams = {
  resource: 'activityNotification';
  operation: 'send';
  authentication?: 'microsoftTeamsOAuth2Api' | 'microsoftOAuth2Api' | 'microsoftEntraServicePrincipalApi';
/**
 * The user who receives the notification in the Teams activity feed. Select the user from the list, or enter the user ID or user principal name. Guest users must be given by their object ID.
 * @searchListMethod getUsers
 * @default {"mode":"list","value":""}
 */
    recipientId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * The bold first line of the notification. Keep it short so it fits on one line.
 */
    headline: string | Expression<string>;
/**
 * The second line of the notification. Teams shows the first 150 characters.
 */
    previewText: string | Expression<string>;
/**
 * The third line of the notification, shown in grey. Name the item that the notification is about, for example the workflow or the order.
 */
    topic: string | Expression<string>;
/**
 * The Microsoft Teams link that opens when the user selects the notification. It must be an https link on a Microsoft Teams domain, for example a chat, channel, message, or meeting link. Microsoft Graph rejects links to n8n or to other websites.
 */
    topicLink: string | Expression<string>;
/**
 * Options
 * @default {}
 */
    options?: {
    /** A number that links related notifications. A new notification with the same Chain ID replaces the earlier one in the activity feed. Leave at 0 to send the notification without a chain.
     * @default 0
     */
    chainId?: number | Expression<number>;
  };
};

export type MicrosoftTeamsV2ActivityNotificationSendOutput = {
  success?: boolean;
};

export type MicrosoftTeamsV2ActivityNotificationSendNode = {
  type: 'n8n-nodes-base.microsoftTeams';
  version: 2;
  config: NodeConfig<MicrosoftTeamsV2ActivityNotificationSendParams> & { credentials?: Credentials };
  output?: Items<MicrosoftTeamsV2ActivityNotificationSendOutput>;
};